/* Confidential NTE records share the existing local persistence and scoped employee directory. */
UR.nteFiles??=[];
let ntTab='journal',ntEmployee='',ntScreen='list',ntSelected='',ntQuery='',ntStatus='All records',ntDraft=null;
const ntCategories=['Attendance','Conduct','Performance','Policy Compliance','Other'];
const ntBase={journal:pdJournalPage,nav:roleNav,openJournal:pdOpenJournal,role:setRole,header:typeof pmsRenderHeader==='function'?pmsRenderHeader:null};
function ntCompany(){return data.pmsActiveCompanyId||'mayon'}
function ntEmployeeAllowed(id){const e=data.employees.find(e=>e[0]===id);return !!e&&pmsGoalEmployeeInCompany(e)&&(viewRole==='Employee'?id===urUser():pdCanJournal(id))}
function ntCanRead(n){return !!n&&n.companyId===ntCompany()&&ntEmployeeAllowed(n.employee)&&(urHr()||!!n.issuedAt)}
function ntCanWrite(n){return urHr()&&(!n||ntCanRead(n))}
function ntVisible(id=''){return UR.nteFiles.filter(n=>ntCanRead(n)&&(!id||n.employee===id)).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))}
function ntNotifications(){return viewRole==='Employee'?ntVisible().filter(n=>n.issuedAt&&!n.readAt):[]}
function ntRecord(id){return UR.nteFiles.find(n=>n.id===id)}
function ntEvent(n,action,detail){n.updatedAt=pdNow();n.history.push({action,by:urUser(),at:n.updatedAt,...(detail?{detail:urClone(detail)}:{})});urAudit('NTE '+action+': '+n.id)}
function ntFail(message){$('#nt-error').textContent=message;return false}
function ntValidDate(value){return /^\d{4}-\d{2}-\d{2}$/.test(value)&&!Number.isNaN(Date.parse(value))&&new Date(value+'T12:00:00Z').toISOString().slice(0,10)===value}
function ntErrors(v){const errors=[];if(!ntEmployeeAllowed(v.employee))errors.push('Choose an employee in the current company.');if(!ntCategories.includes(v.category))errors.push('Choose a category.');if(!v.subject?.trim()||v.subject.length>200)errors.push('Enter a subject of up to 200 characters.');if(!v.body?.trim()||v.body.length>20000)errors.push('Enter the notice body (up to 20,000 characters).');if(!ntValidDate(v.deadline)||v.deadline<urToday)errors.push('Choose an explanation deadline on or after '+date(urToday)+'.');if(v.incidentDate&&(!ntValidDate(v.incidentDate)||v.incidentDate>urToday))errors.push('The incident date must be a valid date on or before today.');if((v.reference||'').length>200)errors.push('Keep the reference within 200 characters.');return errors}
function ntSaveDraft(values,id=''){
 const n=id?ntRecord(id):null;if(!ntCanWrite(n)||id&&!n||n&&n.status!=='Draft')return false;
 const errors=ntErrors(values);if(errors.length)return ntFail(errors.join(' '));
 const v=Object.fromEntries(['employee','category','subject','body','deadline','incidentDate','reference'].map(k=>[k,String(values[k]||'').trim()]));
 if(n&&v.employee!==n.employee)return ntFail('The recipient cannot be changed on an existing draft.');
 const record=n||{id:'NTE-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),companyId:ntCompany(),status:'Draft',createdBy:urUser(),createdAt:pdNow(),history:[]};
 Object.assign(record,v);if(!n)UR.nteFiles.push(record);ntEvent(record,n?'Draft updated':'Draft created');urDirty=false;ntDraft=null;ntSelected=record.id;ntEmployee=record.employee;ntScreen='detail';render();toast('NTE draft saved');return true;
}
function ntIssue(id,confirmed=false){
 const n=ntRecord(id);if(!ntCanWrite(n)||!n||n.status!=='Draft')return false;
 const errors=ntErrors(n);if(errors.length)return ntFail(errors.join(' '));
 if(!confirmed){modal('Issue Notice to Explain?',urPerson(n.employee).name,`<div class="modalbody"><p>This notice will be visible to the employee and their manager. The employee will receive an in-app notification. Its contents will be locked after issuance.</p><p><b>${esc(n.subject)}</b> · Explanation due ${date(n.deadline)}</p></div>`,`<button onclick="closeModal()">Keep as Draft</button><button class="primary" onclick="ntIssue('${n.id}',true)">Issue NTE</button>`);return false}
 n.status='Issued';n.issuedAt=pdNow();n.issuedBy=urUser();n.readAt=null;ntEvent(n,'Issued');closeModal();render();toast('NTE issued; employee notified');return true;
}
function ntRespond(id,body,confirmed=false){
 const n=ntRecord(id);if(viewRole!=='Employee'||!ntCanRead(n)||n.status!=='Issued')return false;
 if(!body?.trim()||body.length>20000)return ntFail('Enter your explanation (up to 20,000 characters).');
 if(!confirmed){ntDraft={response:body};modal('Submit Explanation?','',`<div class="modalbody"><p>Your explanation will be sent to HR and become read-only. You can submit even if the deadline has passed.</p></div>`,`<button onclick="closeModal()">Continue Editing</button><button class="primary" onclick="ntRespond('${n.id}',ntDraft.response,true)">Submit Explanation</button>`);return false}
 n.explanation=body.trim();n.respondedAt=pdNow();n.status='Responded';n.readAt??=pdNow();ntEvent(n,'Explanation submitted');urDirty=false;ntDraft=null;closeModal();render();toast('Explanation submitted to HR');return true;
}
function ntCanCloseNormally(n){return !!n&&!!n.issuedAt&&(n.status==='Responded'&&!!n.explanation||n.status==='Issued'&&ntValidDate(n.deadline)&&n.deadline<urToday)}
function ntFinish(id,status,note,confirmed=false,earlyReason=''){
 const n=ntRecord(id);if(!ntCanWrite(n)||!n||!['Closed','Cancelled'].includes(status)||['Closed','Cancelled'].includes(n.status)||status==='Closed'&&n.status==='Draft')return false;
 if(!note?.trim()||note.length>5000)return ntFail('Enter a '+(status==='Closed'?'closure outcome':'cancellation reason')+' (up to 5,000 characters).');
 const early=status==='Closed'&&!ntCanCloseNormally(n);
 if(early&&(!earlyReason?.trim()||earlyReason.length>5000))return ntFail('The response window remains open. Wait for an explanation or an expired deadline, or use Close Early with Exception and record a separate reason.');
 if(!confirmed){ntDraft={...(ntDraft||{}),note,earlyReason};modal(early?'Close NTE Before Response Deadline?':status==='Closed'?'Close NTE?':'Cancel NTE?','',`<div class="modalbody"><p>${early?'This ends the employee’s opportunity to submit an explanation before the deadline. The exception reason will be visible in the record.':status==='Closed'?'The notice and explanation will remain in the employee’s past records.':'The notice will be retained with its cancellation reason.'}</p>${early?`<p>Response deadline: ${date(n.deadline)}</p><h3>Early Closure Exception</h3><p class="nt-body">${esc(earlyReason)}</p>`:''}<h3>${status==='Closed'?'Closure Outcome':'Cancellation Reason'}</h3><p class="nt-body">${esc(note)}</p></div>`,`<button onclick="closeModal()">Go Back</button><button class="primary" onclick="ntFinish('${n.id}','${status}',ntDraft.note,true,ntDraft.earlyReason||'')">Confirm ${early?'Early Closure':status==='Closed'?'Closure':'Cancellation'}</button>`);return false}
 n.status=status;n[status==='Closed'?'closureNote':'cancelReason']=note.trim();n[status==='Closed'?'closedAt':'cancelledAt']=pdNow();if(early)n.earlyClosureReason=earlyReason.trim();ntEvent(n,early?'Closed early with exception':status,early?{reason:n.earlyClosureReason,deadline:n.deadline,responseReceived:!!n.explanation}:undefined);urDirty=false;ntDraft=null;closeModal();render();toast('NTE '+status.toLowerCase());return true;
}
function ntEarlyClosure(id,note){const n=ntRecord(id);if(!ntCanWrite(n)||!n||n.status!=='Issued'||ntCanCloseNormally(n))return;if(!note?.trim()||note.length>5000)return ntFail('Enter the closure outcome before requesting an early closure.');ntDraft={...(ntDraft||{}),note,earlyReason:ntDraft?.earlyReason||''};modal('Early Closure Exception','Response deadline: '+date(n.deadline),`<div class="modalbody"><p>The employee has not submitted an explanation and the response window remains open. Record why the notice must close early. Cancelling a withdrawn notice is a separate action.</p><label>Separate Exception Reason<textarea id="nt-early-reason" maxlength="5000" rows="4" oninput="ntDraft.earlyReason=this.value;urDirty=true">${esc(ntDraft.earlyReason)}</textarea></label><div id="nt-early-error" class="cw-error" role="alert"></div></div>`,`<button onclick="closeModal()">Keep Response Window Open</button><button class="primary" onclick="ntReviewEarlyClosure('${n.id}')">Review Early Closure</button>`)}
function ntReviewEarlyClosure(id){const n=ntRecord(id);if(!ntCanWrite(n)||!ntDraft)return;const reason=ntDraft.earlyReason||'';if(!reason.trim()||reason.length>5000){$('#nt-early-error').textContent='Enter a separate exception reason (up to 5,000 characters).';return}ntFinish(id,'Closed',ntDraft.note,false,reason)}

function ntSwitch(tab){urGo(()=>{ntTab=tab;ntScreen='list';ntSelected='';ntEmployee='';ntDraft=null;ntQuery='';ntStatus='All records';render()})}
function ntOpenEmployee(id){if(!ntEmployeeAllowed(id))return false;urGo(()=>{page='202 Files';ntTab='nte';ntEmployee=id;ntScreen='list';ntSelected='';ntQuery='';ntStatus='All records';ntDraft=null;render()});return true}
function ntOpenRecord(id){const n=ntRecord(id);if(!ntCanRead(n))return false;urGo(()=>{page='202 Files';ntTab='nte';ntEmployee=n.employee;ntSelected=id;ntScreen='detail';ntDraft=null;if(viewRole==='Employee'&&!n.readAt){n.readAt=pdNow();ntEvent(n,'Read by employee')}if(typeof pmsCloseHeaderMenus==='function')pmsCloseHeaderMenus();render()});return true}
function ntEdit(id=''){const n=id?ntRecord(id):null;if(!ntCanWrite(n)||id&&!n||n&&n.status!=='Draft'||!ntEmployeeAllowed(n?.employee||ntEmployee))return;urGo(()=>{ntSelected=id;ntDraft=urClone(n||{employee:ntEmployee,category:'Attendance',subject:'',body:'',deadline:'',incidentDate:'',reference:''});ntScreen='form';render()})}
function ntSet(key,value){if(!ntDraft)return;ntDraft[key]=value;urDirty=true}
function ntSaveForm(form){if(!form.reportValidity())return;ntSaveDraft(ntDraft,ntSelected)}
function ntIsPast(n){return ['Closed','Cancelled'].includes(n.status)}
function ntBadge(n){return urBadge(n.status)+(n.status==='Issued'&&n.deadline<urToday?'<span class="pill red">Overdue</span>':'')}
function ntTabs(){return viewRole==='Employee'?'':`<div class="tabs nt-tabs" role="tablist" aria-label="202 File sections"><button role="tab" aria-selected="${ntTab==='journal'}" class="${ntTab==='journal'?'active':''}" onclick="ntSwitch('journal')">Journal Entries</button><button role="tab" aria-selected="${ntTab==='nte'}" class="${ntTab==='nte'?'active':''}" onclick="ntSwitch('nte')">NTE Files</button></div>`}
function ntListPage(){
 if(!ntEmployee&&viewRole!=='Employee'){
 const rows=pdScopedEmployees().filter(e=>(e[1]+' '+e[0]+' '+e[2]+' '+e[3]).toLowerCase().includes(ntQuery.toLowerCase()));const key='nte-employees';
 return pdHead('202 Files','Employee journals and confidential Notices to Explain.')+`<section class="panel"><div class="toolbar urtoolbar">${pmsToolbarSearch('Search employees',ntQuery,'ntQuery=this.value;render()')}</div>`+pdTable(['EMPLOYEE','POSITION','DEPARTMENT','ACTIVE NTES','PAST NTES'],pdSlice(key,rows,ntQuery).map(e=>{const ns=ntVisible(e[0]);return `<tr ${pdClickable("ntOpenEmployee('"+e[0]+"')")}><td><b>${esc(e[1])}</b><small>${esc(e[0])}</small></td><td>${esc(e[2])}</td><td>${esc(e[3])}</td><td>${ns.filter(n=>!ntIsPast(n)&&n.status!=='Draft').length}</td><td>${ns.filter(ntIsPast).length}</td></tr>`}).join(''),key,rows.length,'render')+'</section>';
 }
 const id=viewRole==='Employee'?urUser():ntEmployee;if(!ntEmployeeAllowed(id))return urEmpty('NTE files unavailable','Select an employee in your current scope.');
 const p=urPerson(id),records=ntVisible(id).filter(n=>(n.subject+' '+n.category+' '+n.id).toLowerCase().includes(ntQuery.toLowerCase())&&(ntStatus==='All records'||ntStatus==='Active'&&!ntIsPast(n)&&n.status!=='Draft'||ntStatus==='Past'&&ntIsPast(n)||ntStatus==='Draft'&&n.status==='Draft'));
 const key='nte-records-'+id;
 return (viewRole==='Employee'?'':pdBack("ntEmployee='';ntQuery='';render()",'Back to Employee Masterlist'))+pdHead(viewRole==='Employee'?'My NTEs':p.name+' · NTE Files','View active and past Notices to Explain. Drafts are visible to HR only.',urHr()?'<button class="primary" onclick="ntEdit()">Create New NTE</button>':'')+`<section class="panel"><div class="toolbar urtoolbar">${pmsToolbarSearch('Search NTEs',ntQuery,'ntQuery=this.value;render()')}${pmsToolbarSelect('Record status',ntStatus,['All records','Active','Past',...(urHr()?['Draft']:[])],'ntStatus=this.value;render()')}</div>`+pdTable(['NOTICE','CATEGORY','STATUS','EXPLANATION DEADLINE','ISSUED','ACTION'],pdSlice(key,records,ntQuery+ntStatus).map(n=>`<tr><td><b>${esc(n.subject)}</b><small>${esc(n.id)}</small></td><td>${esc(n.category)}</td><td>${ntBadge(n)}</td><td>${date(n.deadline)}</td><td>${n.issuedAt?date(n.issuedAt.slice(0,10)):'Not issued'}</td><td><button onclick="ntOpenRecord('${n.id}')">View NTE</button></td></tr>`).join(''),key,records.length,'render')+'</section>';
}
function ntFormPage(){
 if(!ntDraft||!ntCanWrite(ntSelected?ntRecord(ntSelected):null)||!ntEmployeeAllowed(ntDraft.employee))return ntListPage();const v=ntDraft;
 return pdBack("urGo(()=>{ntScreen=ntSelected?'detail':'list';ntDraft=null;render()})",'Back to NTE Files')+pdHead(ntSelected?'Edit NTE Draft':'Create New NTE',urPerson(v.employee).name+' · HR confidential draft')+`<form class="panel pd-form nt-form" onsubmit="event.preventDefault();ntSaveForm(this)"><div class="notice">Save a draft, review the notice, then issue it to notify the employee. Issued contents cannot be edited. Dates follow the system workflow date: ${date(urToday)}.</div><div class="formgrid"><label>Category<select required onchange="ntSet('category',this.value)">${pdOptions(ntCategories,v.category)}</select></label><label>Explanation Deadline<input required type="date" min="${urToday}" value="${esc(v.deadline)}" onchange="ntSet('deadline',this.value)"></label><label>Incident Date (optional)<input type="date" max="${urToday}" value="${esc(v.incidentDate)}" onchange="ntSet('incidentDate',this.value)"></label><label>Reference (optional)<input maxlength="200" value="${esc(v.reference)}" oninput="ntSet('reference',this.value)"></label></div><label>Subject<input required maxlength="200" value="${esc(v.subject)}" oninput="ntSet('subject',this.value)"></label><label>Notice Body<textarea required maxlength="20000" rows="10" oninput="ntSet('body',this.value)" placeholder="Describe the matter, relevant facts, and what the employee needs to explain.">${esc(v.body)}</textarea></label><div id="nt-error" class="cw-error" role="alert"></div><div class="modalfoot"><button type="button" onclick="urGo(()=>{ntScreen=ntSelected?'detail':'list';ntDraft=null;render()})">Cancel</button><button class="primary" type="submit">Save Draft for Review</button></div></form>`;
}
function ntDetailPage(){
 const n=ntRecord(ntSelected);if(!ntCanRead(n))return urEmpty('NTE unavailable','This notice is outside your access scope.');
 const personal=viewRole==='Employee',hr=ntCanWrite(n);
 return pdBack("urGo(()=>{ntScreen='list';ntSelected='';ntDraft=null;render()})",'Back to NTE Files')+pdHead(n.subject,urPerson(n.employee).name+' · '+n.id,hr&&n.status==='Draft'?`<button onclick="ntEdit('${n.id}')">Edit Draft</button><button class="primary" onclick="ntIssue('${n.id}')">Issue NTE</button>`:'')+`<section class="panel pd-form nt-form"><div class="pd-section-head"><h2>Notice to Explain</h2>${ntBadge(n)}</div><div class="ursummarygrid">${[['Category',n.category],['Explanation Deadline',date(n.deadline)],['Incident Date',n.incidentDate?date(n.incidentDate):'Not specified'],['Reference',n.reference||'—'],['Issued By',n.issuedBy?urPerson(n.issuedBy).name:'Not issued'],['Employee Read Receipt',n.readAt?date(n.readAt.slice(0,10)):'Not yet read']].map(([k,v])=>`<div><small>${k}</small><b>${esc(v)}</b></div>`).join('')}</div><h3>Notice Body</h3><p class="nt-body">${esc(n.body)}</p>${n.status==='Issued'&&n.deadline<urToday?'<div class="notice">The explanation deadline has passed. The employee can still submit an explanation until HR closes or cancels this notice.</div>':''}${n.explanation?`<h3>Employee Explanation</h3><p class="nt-body">${esc(n.explanation)}</p><small>Submitted ${date(n.respondedAt.slice(0,10))}</small>`:''}${n.closureNote?`<h3>Closure Outcome</h3><p class="nt-body">${esc(n.closureNote)}</p>`:''}${n.earlyClosureReason?`<h3>Early Closure Exception</h3><p class="nt-body">${esc(n.earlyClosureReason)}</p>`:''}${n.cancelReason?`<h3>Cancellation Reason</h3><p class="nt-body">${esc(n.cancelReason)}</p>`:''}</section>${personal&&n.status==='Issued'?`<form class="panel pd-form nt-form" onsubmit="event.preventDefault();if(this.reportValidity())ntRespond('${n.id}',this.elements.explanation.value)"><h2>Your Explanation</h2><label>Explanation<textarea name="explanation" required maxlength="20000" rows="6" oninput="ntDraft={response:this.value};urDirty=true">${esc(ntDraft?.response||'')}</textarea></label><p>Review your explanation before submitting. Submitted explanations become read-only.</p><div class="modalfoot"><button class="primary" type="submit">Submit Explanation</button></div></form>`:''}${hr&&!ntIsPast(n)?`<section class="panel pd-form nt-form"><h2>${n.status==='Draft'?'Cancel Draft':'HR Resolution'}</h2>${n.status==='Issued'&&!ntCanCloseNormally(n)?`<div class="notice">The employee’s response window remains open through ${date(n.deadline)}. Normal closure is available after an explanation or after the deadline. Early closure requires a separate exception reason.</div>`:''}<label>${n.status==='Draft'?'Cancellation reason':'Outcome or cancellation reason'}<textarea id="nt-resolution" maxlength="5000" rows="4" oninput="ntDraft={...(ntDraft||{}),note:this.value};urDirty=true">${esc(ntDraft?.note||'')}</textarea></label><div class="modalfoot"><button onclick="ntFinish('${n.id}','Cancelled',$('#nt-resolution').value)">Cancel NTE</button>${n.status!=='Draft'?(ntCanCloseNormally(n)?`<button class="primary" onclick="ntFinish('${n.id}','Closed',$('#nt-resolution').value)">Close NTE</button>`:`<button onclick="ntEarlyClosure('${n.id}',$('#nt-resolution').value)">Close Early with Exception</button>`):''}</div></section>`:''}<div id="nt-error" class="cw-error" role="alert"></div><section class="panel pd-form nt-form"><h3>Record History</h3><ol class="nt-history">${n.history.map(h=>`<li><b>${esc(h.action)}</b> · ${esc(urPerson(h.by).name)}<small>${esc(h.at.replace('T',' ').slice(0,19))}</small>${h.detail?.reason?`<p class="nt-body">${esc(h.detail.reason)}</p>`:''}</li>`).join('')}</ol></section>`;
}
pdJournalPage=function(){const content=viewRole!=='Employee'&&ntTab==='journal'?ntBase.journal():ntScreen==='form'?ntFormPage():ntScreen==='detail'?ntDetailPage():ntListPage();return ntTabs()+content};
pdOpenJournal=function(id){ntTab='journal';return ntBase.openJournal(id)};
roleNav=function(){const rows=ntBase.nav();if(viewRole==='Employee'&&!rows.some(r=>r[0]==='202 Files'))rows.splice(rows.findIndex(r=>r[0]==='Reviews')+1,0,['202 Files','']);return rows};
setRole=function(role){urGo(()=>{ntTab=role==='Employee'?'nte':'journal';ntEmployee='';ntSelected='';ntScreen='list';ntDraft=null;ntQuery='';ntStatus='All records';ntBase.role(role)})};
if(ntBase.header)pmsRenderHeader=function(){ntBase.header();const notices=ntNotifications(),menu=$('#pmsNotificationsMenu'),button=$('#pmsNotificationsButton');if(menu&&notices.length&&data.pmsNotificationsEnabled){menu.innerHTML=menu.innerHTML.replace('<p class="pms-menu-empty">You’re up to date.</p>','')+`<div class="pms-menu-title">NOTICES TO EXPLAIN (${notices.length})</div>${notices.map(n=>`<button type="button" class="pms-notice-item" onclick="ntOpenRecord('${n.id}')"><b>${esc(n.subject)}</b><small>Explanation due ${date(n.deadline)} · ${esc(n.status)}</small></button>`).join('')}`}if(button){button.classList.toggle('nt-unread',!!notices.length);button.setAttribute('aria-label',notices.length?'Notifications · '+notices.length+' unread NTEs':'Notifications')}};
render();
